# Fixed-origination validation of supplied operational vintage performance.
vintage_backtest<-function(vintage_table,account_predictions,account_outcomes,origin_cohorts,denominator_contract,design,uncertainty,cluster_resamples=NULL,confidence_level=.95,context=NULL){
 d<-.vb_design(design,context);table<-.vr_rows(vintage_table,'vintage_table');predictions<-.vr_rows(account_predictions,'account_predictions');outcomes<-.vr_rows(account_outcomes,'account_outcomes');origins<-.vr_rows(origin_cohorts,'origin_cohorts');contract<-.ex_object(denominator_contract,'denominator_contract');if(d$target$time_unit!='months'||floor(d$target$horizon)!=d$target$horizon||d$target$conditioning!='performing').cr_error('VINTAGE_TARGET','Whole-month maximum MOB and performing-at-origin target required');if(!identical(contract$method,'fixed_origination')||!contract$weighting%in%c('count','original_balance')||!identical(contract$exit_treatment,'first_competing_exit')).cr_error('VINTAGE_DENOMINATOR','Declare fixed count/balance denominator and first competing exit');for(key in c('reference','default_definition','horizon_convention')).vb_string(contract[[key]],key);if(contract$horizon_convention!='origination_month_end_plus_mob').cr_error('VINTAGE_HORIZON','Use cohort month-end plus MOB');.ex_ids(lapply(origins,function(r)r$account_id),'origin account IDs',empty=TRUE);members<-origin_index<-list();weights<-numeric();sampling_rows<-list();groupkey<-function(cohort,currency).cr_hash(list(cohort,currency));pairkey<-function(account,mob).cr_hash(list(account,mob))
 for(i in seq_along(origins)){row<-origins[[i]];account<-row$account_id;opened<-.cr_data_date(row$opened_at,'opened_at');known<-.cr_data_date(row$known_at,'known_at');.vb_string(row$currency,'currency');.vb_string(row$cluster_id,'cluster_id');balance<-.vb_number(row$original_balance,'original_balance',0);if(known<opened||known>.cr_data_date(d$evaluation_cutoff,'evaluation_cutoff')).cr_error('VINTAGE_ORIGIN','Origin must be known by evaluation, not before opening');key<-groupkey(substr(row$opened_at,1,7),row$currency);members[[key]]<-c(members[[key]],i);origin_index[[account]]<-i;weights<-c(weights,if(contract$weighting=='count')1 else balance);sampling_rows[[i]]<-list(cluster_id=row$cluster_id,entity_id=account)}
 make_index<-function(rows,label){index<-list();for(row in rows){account<-row$account_id;mob<-.vb_number(row$months_on_book,'months_on_book',0);if(is.null(account)||!account%in%names(origin_index)||floor(mob)!=mob||mob>d$target$horizon).cr_error('VINTAGE_ACCOUNT','Known account/integer MOB required');key<-pairkey(account,mob);if(!is.null(index[[key]])).cr_error('VINTAGE_DUPLICATE',paste('Duplicate account/MOB',label));index[[key]]<-row};index};pred_index<-make_index(predictions,'prediction');outcome_index<-make_index(outcomes,'outcome');cells<-list();seen<-used_predictions<-used_outcomes<-character();cutoff<-.cr_data_date(d$evaluation_cutoff,'evaluation_cutoff');draws<-.vb_draws(uncertainty,cluster_resamples,sampling_rows,confidence_level);if(length(table))table<-table[order(vapply(table,function(c)c$cohort,character(1)),vapply(table,function(c)c$currency,character(1)),vapply(table,function(c)c$months_on_book,numeric(1)))]
 for(cell in table){cohort<-.vb_string(cell$cohort,'cohort');currency<-.vb_string(cell$currency,'currency');mob<-.vb_number(cell$months_on_book,'months_on_book',0);key<-.cr_hash(list(cohort,currency,mob));if(mob!=floor(mob)||key%in%seen).cr_error('VINTAGE_CELL','Unique integer-MOB cells required');seen<-c(seen,key);indices<-members[[groupkey(cohort,currency)]];end<-.cr_beh_month(.cr_data_date(paste0(cohort,'-01'),'cohort month'),mob,TRUE);if(!length(indices)||!identical(cell$period_end,as.character(end))).cr_error('VINTAGE_CELL','Known original cohort/exact MOB endpoint required');N<-length(indices);balance<-sum(vapply(origins[indices],function(r)r$original_balance,numeric(1)));if(cell$accounts!=N||is.null(cell$original_balance)||abs(cell$original_balance-balance)>1e-10*max(1,balance)).cr_error('VINTAGE_DENOMINATOR','Exits cannot shrink original membership denominator');cumulative<-interval<-numeric();observed_cumulative<-observed_interval<-list();complete<-exits<-logical();gaps<-character()
 for(i in indices){origin<-origins[[i]];account<-origin$account_id;pair<-pairkey(account,mob);prediction<-pred_index[[pair]];outcome<-outcome_index[[pair]];if(is.null(prediction)).cr_error('VINTAGE_PREDICTION','Every original account including exits needs prediction');used_predictions<-c(used_predictions,pair);for(field in c('model_id','model_version','parameter_version'))if(!identical(prediction[[field]],d[[field]])).cr_error('VINTAGE_VERSION','Prediction differs from frozen design');at<-.cr_data_date(prediction$forecast_at,'forecast_at');known<-.cr_data_date(prediction$known_at,'prediction known_at');if(at!=.cr_data_date(origin$opened_at,'opened_at')||known>at).cr_error('VINTAGE_LOOKAHEAD','Forecast must be frozen at original opening');pc<-.vb_number(prediction$cumulative_pd,'cumulative_pd',0);pi<-.vb_number(prediction$interval_pd,'interval_pd',0);if(pc>1||pi>pc).cr_error('VINTAGE_PD','Ordered cumulative/interval PD in [0,1] required');cumulative<-c(cumulative,pc);interval<-c(interval,pi);iscomplete<-FALSE;yc<-yi<-NULL;exited<-FALSE
 if(!is.null(outcome)){used_outcomes<-c(used_outcomes,pair);when<-.cr_data_date(outcome$known_at,'outcome known_at');if(!identical(outcome$period_end,as.character(end))||!identical(outcome$default_definition,contract$default_definition)).cr_error('VINTAGE_TARGET','Account target/end differs from contract');isbool<-function(v)is.logical(v)&&length(v)==1&&!is.na(v);if(!isbool(outcome$complete)||!isbool(outcome$exited)).cr_error('VINTAGE_OUTCOME','Complete/exit Boolean flags required');if(when<.cr_data_date(origin$opened_at,'opened_at')).cr_error('VINTAGE_LOOKAHEAD','Outcome cannot be known before origin');if(when<=cutoff){iscomplete<-outcome$complete;yc<-outcome$cumulative_default;yi<-outcome$interval_default;exited<-outcome$exited;for(v in list(yc,yi))if(!is.null(v)&&(!is.numeric(v)||length(v)!=1||!v%in%c(0,1))).cr_error('VINTAGE_OUTCOME','Observed indicators must be binary/null');if(iscomplete&&(is.null(yc)||is.null(yi))).cr_error('VINTAGE_OUTCOME','Complete paths require observed indicators');if((!is.null(yc)&&!is.null(yi)&&yi>yc)||(exited&&isTRUE(yc==1))).cr_error('VINTAGE_OUTCOME','First-event labels inconsistent');if(isTRUE(yc==1)||exited){.vb_string(outcome$event_id,'first event_id');event_at<-.cr_data_date(outcome$first_event_at,'first_event_at');if(!iscomplete||event_at<.cr_data_date(origin$opened_at,'opened_at')||event_at>end||event_at>when).cr_error('VINTAGE_EVENT','First event must be observed inside origin-to-end window');previous_end<-.cr_beh_month(.cr_data_date(paste0(cohort,'-01'),'cohort month'),mob-1,TRUE);if(isTRUE(yc==1)&&yi!=as.integer(event_at>previous_end)).cr_error('VINTAGE_EVENT','Interval default outside calendar MOB interval')}else if(iscomplete){through<-.cr_data_date(outcome$complete_through,'complete_through');if(through<end||through>when).cr_error('VINTAGE_FOLLOWUP','No-event complete outcomes require endpoint coverage')}}}
 if(!iscomplete)gaps<-c(gaps,account);observed_cumulative[length(observed_cumulative)+1]<-list(yc);observed_interval[length(observed_interval)+1]<-list(yi);complete<-c(complete,iscomplete);exits<-c(exits,exited)}
 counts<-list(defaults=sum(vapply(observed_cumulative,function(y)isTRUE(y==1),logical(1))),incidence=sum(vapply(observed_interval,function(y)isTRUE(y==1),logical(1))),exits=sum(exits),complete_accounts=sum(complete));if(any(vapply(names(counts),function(k)is.null(cell[[k]])||cell[[k]]!=counts[[k]],logical(1)))).cr_error('VINTAGE_RECONCILIATION','Operational counts differ from account outcomes');mature<-end<=cutoff&&all(complete);if(!identical(cell$mature,mature)).cr_error('VINTAGE_MATURITY','Calendar/original follow-up maturity conflict');for(field in c('cumulative_default_rate','incidence_rate')){count<-if(field=='cumulative_default_rate')counts$defaults else counts$incidence;expected<-if(mature)count/N else NULL;if(is.null(cell[[field]])!=is.null(expected)||(!is.null(expected)&&abs(cell[[field]]-expected)>1e-12)).cr_error('VINTAGE_RECONCILIATION','Rate violates original denominator or maturity')};cells[[length(cells)+1]]<-list(key=list(cohort,currency,mob),indices=indices,period_end=as.character(end),original_accounts=N,original_balance=balance,mature=mature,counts=counts,missing_followup_accounts=as.list(gaps),remaining_first_event_risk_count=N-counts$defaults-counts$exits,cumulative=cumulative,interval=interval,observed_cumulative=vapply(observed_cumulative,function(y)if(is.null(y))0 else y,numeric(1)),observed_interval=vapply(observed_interval,function(y)if(is.null(y))0 else y,numeric(1)))}
 if(!setequal(names(pred_index),used_predictions)||!setequal(names(outcome_index),used_outcomes)).cr_error('VINTAGE_COVERAGE','Prediction/outcome cells must match operational table');for(account in names(origin_index)){ps<-Filter(function(r)r$account_id==account,predictions);ages<-sort(vapply(ps,function(r)r$months_on_book,numeric(1)));if(length(ages)>1)for(i in seq_len(length(ages)-1)){before<-ages[i];after<-ages[i+1];a<-pred_index[[pairkey(account,before)]];b<-pred_index[[pairkey(account,after)]];if(b$cumulative_pd<a$cumulative_pd-1e-12).cr_error('VINTAGE_CURVE','Cumulative forecast decreases');if(after==before+1&&abs(b$interval_pd-(b$cumulative_pd-a$cumulative_pd))>1e-12).cr_error('VINTAGE_CURVE','Interval differs from cumulative increment')}}
 calculate<-function(draw){lapply(cells,function(cell){weight<-weights[cell$indices]*draw[cell$indices];metrics<-list();for(label in c('cumulative','interval')){p<-cell[[label]];y<-cell[[paste0('observed_',label)]];w<-if(cell$mature)weight else rep(0,length(weight));m<-.vb_errors(p,y,w);m['brier']<-list(if(sum(w)>0)sum((w/sum(w))*(p-y)^2)else NULL);metrics[[label]]<-m};c(list(cohort=cell$key[[1]],currency=cell$key[[2]],months_on_book=cell$key[[3]],period_end=cell$period_end,original_accounts=cell$original_accounts,original_balance=cell$original_balance,original_weight_sum=sum(weight),mature=cell$mature,counts=cell$counts,remaining_first_event_risk_count=cell$remaining_first_event_risk_count,missing_followup_accounts=cell$missing_followup_accounts),metrics)})};values<-calculate(rep(1,length(origins)));samples<-if(is.null(draws))NULL else lapply(draws,function(draw){result<-calculate(draw);sample<-list();for(r in result)for(label in c('cumulative','interval'))for(metric in c('bias','brier'))sample[paste(r$cohort,r$currency,r$months_on_book,label,metric,sep='/')]<-list(r[[label]][[metric]]);sample});applicable<-any(vapply(cells,function(c)c$mature,logical(1)));value<-list(artifact_type='ValidationResult',metrics=list(cells=values),uncertainty=.vb_bands(samples,confidence_level),design=d,denominator_contract=contract,applicability=if(applicable)'APPLICABLE'else'NOT_APPLICABLE',reason=if(applicable)NULL else'NO_COMPLETE_MATURE_VINTAGE',decision=list(status='NOT_ASSESSED'),original_cohort_fingerprint=.cr_hash(origins),operational_table_fingerprint=.cr_hash(table),prediction_fingerprint=.cr_hash(predictions),outcome_fingerprint=.cr_hash(outcomes),survivorship_denominator_preserved=TRUE,censoring_adjustment='NONE_INCOMPLETE_CELLS_NOT_ESTIMABLE');.cr_result(value,'validation.vintage_backtest','vintage_validation',context,limitations='Validates supplied operational tables and separate account outcomes. Fixed denominators retain exits; incomplete original cohorts are not reweighted into performance claims. Cluster intervals condition on forecasts; MOB uses cohort calendar month ends.')
}
